前言修改博客时觉得主页大图加载太慢，而且为了加载快一点已经把图片弄得很糊了，效果还是不好正好发现了这位大佬的文章，首页背景图渐进式加载，解决卡顿难题正好解决了加载过慢和图片不能太清晰的问题但夜间模式下的深色遮罩又没了，所以分享一下解决方法安知鱼和butterfly主题适用  
首页背景图渐进式加载（转载）新建文件新建文件source/js/imgloaded.js新增以下内容，并按照注释调整图片路径  
// 首页头图加载优化  /**   * @description 实现medium的渐进加载背景的效果   */  class ProgressiveLoad &#123;      constructor(smallSrc, largeSrc) &#123;      this.smallSrc = smallSrc;      this.largeSrc = largeSrc;      this.initTpl();    &#125;      /**     * @description 生成ui模板     */    initTpl() &#123;      this.container = document.createElement(&#x27;div&#x27;);      this.smallStage = document.createElement(&#x27;div&#x27;);      this.largeStage = document.createElement(&#x27;div&#x27;);      this.smallImg = new Image();      this.largeImg = new Image();      this.container.className = &#x27;pl-container&#x27;;      this.smallStage.className = &#x27;pl-img pl-blur&#x27;;      this.largeStage.className = &#x27;pl-img&#x27;;      this.container.appendChild(this.smallStage);      this.container.appendChild(this.largeStage);      this.smallImg.onload = this._onSmallLoaded.bind(this);      this.largeImg.onload = this._onLargeLoaded.bind(this);    &#125;      /**     * @description 加载背景     */    progressiveLoad() &#123;      this.smallImg.src = this.smallSrc;      this.largeImg.src = this.largeSrc;    &#125;      /**     * @description 大图加载完成     */    _onLargeLoaded() &#123;      this.largeStage.classList.add(&#x27;pl-visible&#x27;);      this.largeStage.style.backgroundImage = `url(&#x27;$&#123;this.largeSrc&#125;&#x27;)`;    &#125;      /**     * @description 小图加载完成     */    _onSmallLoaded() &#123;      this.smallStage.classList.add(&#x27;pl-visible&#x27;);      this.smallStage.style.backgroundImage = `url(&#x27;$&#123;this.smallSrc&#125;&#x27;)`;    &#125;  &#125;      const executeLoad = (config, target) =&gt; &#123;      console.log(&#x27;执行渐进背景替换&#x27;);    const isMobile = window.matchMedia(&#x27;(max-width: 767px)&#x27;).matches;    const loader = new ProgressiveLoad(      isMobile ? config.mobileSmallSrc : config.smallSrc,      isMobile ? config.mobileLargeSrc : config.largeSrc    );    // 和背景图颜色保持一致，防止高斯模糊后差异较大    if (target.children[0]) &#123;      target.insertBefore(loader.container, target.children[0]);    &#125;    loader.progressiveLoad();  &#125;;      const config = &#123;      smallSrc: &#x27;/img/xiaotu.jpg&#x27;, // 小图链接 尽可能配置小于100k的图片    largeSrc: &#x27;/img/tu.jpg&#x27;, // 大图链接 最终显示的图片    mobileSmallSrc: &#x27;/img/sjxt.jpg&#x27;, // 手机端小图链接 尽可能配置小于100k的图片    mobileLargeSrc: &#x27;/img/sjdt.jpg&#x27;, // 手机端大图链接 最终显示的图片    enableRoutes: [&#x27;/&#x27;],    &#125;;  function initProgressiveLoad(config) &#123;      const target = document.getElementById(&#x27;page-header&#x27;);    if (target &amp;&amp; target.classList.contains(&#x27;full_page&#x27;)) &#123;      executeLoad(config, target);    &#125;  &#125;      function onPJAXComplete(config) &#123;      const target = document.getElementById(&#x27;page-header&#x27;);    if (target &amp;&amp; target.classList.contains(&#x27;full_page&#x27;)) &#123;      initProgressiveLoad(config);    &#125;  &#125;    document.addEventListener(&quot;DOMContentLoaded&quot;, function() &#123;      initProgressiveLoad(config);  &#125;);      document.addEventListener(&quot;pjax:complete&quot;, function() &#123;      onPJAXComplete(config);  &#125;);    

新建文件source/css/imgloaded.css新增以下内容，并按照注释自行决定调整内容  
/* 首页头图加载 */  .pl-container &#123;    width: 100%;    height: 100%;    position: relative;    overflow: hidden;    will-change: transform; /* 添加性能优化 */    animation: blur-to-clear 2s cubic-bezier(.62,.21,.25,1) 0s 1 normal backwards running, scale 1.5s cubic-bezier(.62,.21,.25,1) 0s 1 both;  &#125;  .pl-img &#123;    width: 100%;    height: 100%;    position: absolute;    background-position: center;    background-size: cover;    background-repeat: no-repeat;    opacity: 0;    transition: opacity 1s;  &#125;  @keyframes blur-to-clear &#123;    0% &#123;      filter: blur(50px);    opacity: 1;  &#125;    100% &#123;      filter: blur(0);    opacity: 1;  &#125;  &#125;  @keyframes scale &#123;    0% &#123;      transform: scale(1.5) translateZ(0);    opacity: 0;  &#125;    to &#123;      transform: scale(1) translateZ(0);    opacity: 1;  &#125;  &#125;  .pl-visible &#123;    opacity: 1;  &#125;  .pl-blur &#123;    /* 小图锯齿多，增加高斯模糊 */    filter: blur(50px);  &#125;  
引入文件在inject里引入即可  
inject:    head:      - &lt;link rel=&quot;stylesheet&quot; href=&quot;/css/imgloaded.css?1&quot;&gt;  bottom:      - &lt;script async data-pjax src=&quot;/js/imgloaded.js?1&quot;&gt;&lt;/script&gt; # 首页图片渐进式加载
夜间模式深色遮罩也很简单，在css里加入这一段即可  
/* 深色模式遮罩 */  [data-theme=&quot;dark&quot;] .pl-container::after &#123;    content: &quot;&quot;;    position: absolute;    top: 0;    left: 0;    width: 100%;    height: 100%;    background: rgba(0, 0, 0, 0.3); /* 30%透明度的黑色遮罩 */    z-index: 1;  &#125;  
回到终端，执行hexo三连就完成了！

