先看效果源码原地址：CodePen:Parametric Spider稍微修改了一下，去掉了设置和署名，分享一下代码

HTML里要引入https://unpkg.co/gsap@3/dist/gsap.min.js 和 https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js然后再放上
&lt;canvas id=&quot;spidercanvas&quot; /&gt;
即可如果想要一个按钮可以打开或关闭它的话，可以加上
&lt;button onclick=&quot;spider()&quot; id=&quot;spiderbutton&quot;&gt;蜘蛛，启动！&lt;/button&gt;


JS文件:
/*--------------------Vars--------------------*/const canvas = document.querySelector(&quot;#spidercanvas&quot;);const ctx = canvas.getContext(&quot;2d&quot;);const button = document.getElementById(&quot;spiderbutton&quot;);const win = &#123;  w: window.innerWidth,  h: window.innerHeight&#125;;const mouse = &#123;  x: win.w * 0.5,  y: win.h * 0.5,  lerpX: win.w * 0.5,  lerpY: win.h * 0.5,  stepX: 0,  stepY: 0,  oldStepX: 0,  oldStepY: 0,  angle: 0&#125;;const opts = &#123;  cellSize: 40,  pawRadius: 94,  pawHeight: 200,  pawRandomStep: 0.2,  bodyHeight: 20,  spiderOffsetX: 30,  spiderOffsetY: 40,  shadowY: 0.3,  speed: 0.12,  stop: false,  jump: 0&#125;;let cols = 0;let rows = 0;canvas.style.display = &quot;block&quot;;/*--------------------button--------------------*/function spider() &#123;  if (canvas.style.display == &quot;none&quot;) &#123;    canvas.style.display = &quot;block&quot;;  &#125; else &#123;    canvas.style.display = &quot;none&quot;;  &#125;&#125;/*--------------------Lerp--------------------*/const lerp = (a, b, c) =&gt; &#123;  return (1 - c) * a + c * b;&#125;;/*--------------------Random--------------------*/const random = (start, range) =&gt; &#123;  return start - range + Math.random() * range * 2;&#125;;/*--------------------Resize--------------------*/const handleResize = () =&gt; &#123;  win.w = window.innerWidth;  win.h = window.innerHeight;  canvas.width = win.w;  canvas.height = win.h;  cols = Math.round(win.w / opts.cellSize) + 1;  rows = Math.round(win.h / opts.cellSize) + 1;&#125;;handleResize();window.addEventListener(&quot;resize&quot;, handleResize);/*--------------------Paws--------------------*/const Paws = [  &#123; x: win.w * 0.5, y: win.h * 0.5 &#125;,  &#123; x: win.w * 0.5, y: win.h * 0.5 &#125;,  &#123; x: win.w * 0.5, y: win.h * 0.5 &#125;,  &#123; x: win.w * 0.5, y: win.h * 0.5 &#125;,  &#123; x: win.w * 0.5, y: win.h * 0.5 &#125;,  &#123; x: win.w * 0.5, y: win.h * 0.5 &#125;,  &#123; x: win.w * 0.5, y: win.h * 0.5 &#125;,  &#123; x: win.w * 0.5, y: win.h * 0.5 &#125;];/*--------------------Clear--------------------*/const clear = () =&gt; &#123;  ctx.clearRect(0, 0, win.w, win.h);&#125;;/*--------------------Circle--------------------*/const circle = (x, y, r, c) =&gt; &#123;  ctx.fillStyle = c;  ctx.beginPath();  ctx.ellipse(x, y, r, r, 0, 0, Math.PI * 2);  ctx.fill();  ctx.closePath();&#125;;/*--------------------Rect--------------------*/const rect = (x, y, r, c) =&gt; &#123;  ctx.fillStyle = c;  ctx.fillRect(x, y, r, r);&#125;;/*--------------------Walk--------------------*/const walk = () =&gt; &#123;  let ind = 0;  Array(10)    .fill()    .forEach((a, i) =&gt; &#123;      const theta = i / 10;      if (i % 5 === 0) return;      const x = random(        mouse.x + cols * 0.5 + opts.pawRadius * Math.sin(theta * Math.PI * 2),        opts.pawRadius * opts.pawRandomStep      );      const y = random(        mouse.y + rows * 0.5 + opts.pawRadius * Math.cos(theta * Math.PI * 2),        opts.pawRadius * opts.pawRandomStep      );      gsap.to(Paws[ind++], &#123;        x,        y,        duration: opts.speed,        ease: &quot;power3.out()&quot;,        delay: ((i + 2) % 4) * 0.1      &#125;);    &#125;);&#125;;/*--------------------Check Step--------------------*/const checkStep = () =&gt; &#123;  mouse.stepX = Math.round((mouse.x / win.w) * (cols - 1)) * opts.cellSize;  mouse.stepY = Math.round((mouse.y / win.h) * (rows - 1)) * opts.cellSize;  if (mouse.oldStepX !== mouse.stepX || mouse.oldStepY !== mouse.stepY) &#123;    walk();  &#125;  mouse.oldStepX = mouse.stepX;  mouse.oldStepY = mouse.stepY;  // rect(mouse.stepX, mouse.stepY, opts.cellSize, &#x27;rgba(255, 0, 0, .1)&#x27;)&#125;;/*--------------------Draw Spider--------------------*/const drawSpider = () =&gt; &#123;  const x = mouse.lerpX - opts.spiderOffsetX;  const y = mouse.lerpY - opts.spiderOffsetY;  // Shadows  Paws.forEach((p, i) =&gt; &#123;    ctx.strokeStyle = &quot;#eee&quot;;    ctx.lineWidth = 1;    ctx.beginPath();    ctx.moveTo(x, y + opts.bodyHeight);    const x2 = lerp(x, p.x, 0.5);    const y2 = lerp(y + opts.jump, p.y, opts.shadowY);    ctx.quadraticCurveTo(x2, y2, p.x, p.y);    ctx.stroke();    ctx.closePath();  &#125;);  // Paws  Paws.forEach((p, i) =&gt; &#123;    ctx.strokeStyle = &quot;black&quot;;    ctx.lineWidth = 1;    ctx.beginPath();    ctx.moveTo(x, y + opts.jump);    const x1 = lerp(x, p.x, 0.5);    const y1 = lerp(y + opts.jump, p.y - opts.pawHeight, 0.5);    ctx.quadraticCurveTo(x1, y1, p.x, p.y);    ctx.stroke();    ctx.closePath();  &#125;);  // Head&#125;;/*--------------------Draw Mouse--------------------*/const drawMouse = () =&gt; &#123;  mouse.lerpX = lerp(mouse.lerpX, mouse.x, 0.1);  mouse.lerpY = lerp(mouse.lerpY, mouse.y, 0.1);  if (opts.stop) &#123;    mouse.lerpX = win.w * 0.5;    mouse.lerpY = win.h * 0.5;    mouse.x = win.w * 0.5;    mouse.y = win.h * 0.5;  &#125;  checkStep();&#125;;/*--------------------Draw--------------------*/const draw = (t) =&gt; &#123;  clear();  drawMouse();  drawSpider();  requestAnimationFrame(draw);&#125;;draw();/*--------------------Mouse--------------------*/const handleMouseMove = (e) =&gt; &#123;  if (opts.stop) &#123;    mouse.lerpX = win.w * 0.5;    mouse.lerpY = win.h * 0.5;    mouse.x = win.w * 0.5;    mouse.y = win.h * 0.5;  &#125; else &#123;    mouse.x = e.clientX;    mouse.y = e.clientY;  &#125;&#125;;const handleTouchMove = (e) =&gt; &#123;  mouse.x = e.touches[0].clientX;  mouse.y = e.touches[0].clientY;&#125;;const handleMouseDown = () =&gt; &#123;  if (opts.stop) return;  gsap.killTweensOf(opts);  gsap.to(opts, &#123;    jump: opts.bodyHeight,    duration: 0.5,    ease: &quot;power3.out&quot;  &#125;);&#125;;const handleMouseUp = () =&gt; &#123;  if (opts.stop) return;  gsap.killTweensOf(opts);  gsap.to(opts, &#123;    jump: 0,    duration: 2,    ease: &quot;elastic(1.4, 0.1)&quot;  &#125;);&#125;;window.addEventListener(&quot;mousemove&quot;, handleMouseMove);window.addEventListener(&quot;touchstart&quot;, handleTouchMove);window.addEventListener(&quot;touchmove&quot;, handleTouchMove);window.addEventListener(&quot;mousedown&quot;, handleMouseDown);window.addEventListener(&quot;mouseup&quot;, handleMouseUp);

